{"code": "import pandas as pd
df3 = pd.read_excel('SoBanHang.xlsx', sheet_name='Tháng 03-2025')
df4 = pd.read_excel('SoBanHang.xlsx', sheet_name='Tháng 04-2025')
df = pd.concat([df3, df4], ignore_index=True)

def parse_date(v):
    if isinstance(v,(int,float)):
        return pd.Timestamp(1899,12,30)+pd.Timedelta(days=v)
    s=str(v).strip()
    for fmt in ('%d/%m/%Y','%d/%m','%Y/%m/%d','%d-%m','%Y-%m-%d'):
        try: return pd.to_datetime(s, format=fmt)
        except: pass
    return pd.NaT
df['d']=df['Ngày lập'].apply(parse_date)

def parse_money(v):
    if isinstance(v,(int,float)): return float(v)
    s=str(v).strip(); neg=s.startswith('-'); s=s.replace('-','')
    s=s.replace('đ','').replace('.','').replace(',','')
    parts=s.split('tr'); a=parts[0].strip(); b=parts[1].strip() if len(parts)>1 else ''
    try: val=int(a)*1000000+int(b)*1000 if a or b else 0
    except: 
        try: val=int(s)
        except: return float('nan')
    return -float(val) if neg else float(val)
df['money']=df['Tiền'].apply(parse_money)

def status_ok(s):
    s=str(s).strip()
    if s in ('hủy','Hủy'): return False
    if s in ('trả lại','Đã trả hàng'): return False
    return True
df['ok']=df['Ghi chú TT'].apply(status_ok)

# investigate big money rows
big=df[df['money'].abs()>1e8]
print('big rows:')
print(big[['Mã phiếu','Ngày lập','Tiền','Ghi chú TT','Số lượng hàng','Tên SP']].to_string())

start=pd.Timestamp('2025-03-27'); end=pd.Timestamp('2025-04-25')
sub=df[(df['d']>=start)&(df['d']<=end)]
print('rows in window:', len(sub))
good=sub[sub['ok']]
print('good rows:', len(good))
neg=good[good['Số lượng hàng'].astype(str).str.contains('-', na=False)]
print('neg qty in good:', len(neg))
print('revenue (incl big):', round(good['money'].sum()))
"}

